-- 02: DML CRUD Operations

-- Create (Insert)
INSERT INTO departments (id, name) VALUES (4, 'Human Resources');

-- Read (Select)
SELECT name, salary FROM employees WHERE salary > 100000;

-- Update
UPDATE employees SET salary = salary * 1.10 WHERE department_id = 1;

-- Delete
DELETE FROM employees WHERE id = 999;

-- 09: B-Tree Index Creation

-- Single column index
CREATE INDEX idx_employees_email ON employees(email);

-- Composite index (Order matters! Leftmost prefix rule)
CREATE INDEX idx_emp_dept_salary ON employees(department_id, salary DESC);

-- 11: ACID Transaction Block
BEGIN TRANSACTION;

UPDATE employees SET salary = salary - 5000 WHERE id = 101;
UPDATE employees SET salary = salary + 5000 WHERE id = 102;

-- Commit if all succeed, or ROLLBACK on failure
COMMIT;

-- 12: Pessimistic Locking with SELECT FOR UPDATE (Postgres/MySQL syntax)
-- BEGIN;
-- SELECT * FROM employees WHERE id = 101 FOR UPDATE;
-- UPDATE employees SET salary = salary + 1000 WHERE id = 101;
-- COMMIT;

-- 15: Trigger Audit Pattern
CREATE TABLE audit_log (
    id INTEGER PRIMARY KEY,
    action TEXT NOT NULL,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TRIGGER after_employee_insert
AFTER INSERT ON employees
BEGIN
    INSERT INTO audit_log (action) VALUES ('New employee created');
END;

-- 17: Classic Interview Query: Find 2nd Highest Salary in Company
SELECT MAX(salary) AS second_highest_salary
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

-- Alternatively with DENSE_RANK():
WITH RankedSalaries AS (
    SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) as rank
    FROM employees
)
SELECT salary FROM RankedSalaries WHERE rank = 2 LIMIT 1;
